from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
OUT=ROOT/'brake-estimate'
data=json.loads((ROOT/'assembly.json').read_text())
ids=['caliper','brake-arm','barrel-adjuster','rear-adjuster','brake-pivot','adapter','pm-bolts','pads','brake-wire','cable-lead']
data=[dict(d,file=d['id']+'-ESTIMATE.stl',reference=True) for d in data if d['id'] in ids]
for d in data:
 d['explode']={'caliper':[0,0,0],'adapter':[0,0,-40],'brake-arm':[0,0,35],'rear-adjuster':[0,0,-55],'barrel-adjuster':[0,-30,0],'brake-pivot':[0,0,65],'pads':[-30,0,0],'pm-bolts':[30,0,0],'brake-wire':[0,0,35],'cable-lead':[0,-30,0]}[d['id']]
(OUT/'assembly.json').write_text(json.dumps(data,separators=(',',':')))
head=(ROOT/'viewer.template.html').read_text().split('</head>')[0].replace('<title>Motor-mounted brake · CAD</title>','<title>CMD-23 · estimated model</title>')+'</head>'
html=head+'''<body data-mode="brake"><header><div><h1>CMD-23 · estimated geometry</h1><p>Images + standard interfaces. Reference geometry only.</p></div><span class="tag">Image estimate · R06</span></header><div class="layout"><aside><div class="control"><h2>Brake model</h2><p class="small">Approx.55 ×110 ×60 mm including controls.<br>Radial ×tangential ×axial. Not measured.</p><label for="explode">Exploded view <output id="explodedValue">0%</output></label><input id="explode" type="range" min="0" max="100" value="0"><div class="buttons"><button id="assembled">Assembled</button><button id="exploded">Exploded</button></div><input id="transparent" type="checkbox" hidden><input id="fasteners" type="checkbox" checked hidden><input id="motorVisible" type="checkbox" checked hidden></div><h2>Parts</h2><div class="parts" id="parts"></div><div class="detail" id="detail">Select a part. Drag to orbit. Scroll to zoom.</div><div class="buttons" style="margin-top:10px"><button id="isolate">Isolate selected</button><button id="showAll">Show all</button></div><p class="notice"><strong>Fit not confirmed.</strong> Body contours, bracket offsets and cable motion are inferred. The estimate conflicts with the R05 housing at the assumed position.</p><p class="small"><a href="estimate-report.html">Sources, uncertainty &amp; fit findings ↗</a><br><a href="../index.html">Compare with housing ↗</a><br><a href="CMD23-caliper-assembly-ESTIMATE.stl" download>Reference assembly STL ↓</a><br><a href="CMD23-layout-ESTIMATE.glb" download>Layout GLB ↓</a></p><footer>Standard anchors: IS51 / PM74.17 mm.<br>Controls and internal mechanism not validated.<br>Do not manufacture an operating brake from these meshes.</footer></aside><main id="stage"><div class="toolbar"><button data-view="iso">Isometric</button><button data-view="front">Front</button><button data-view="side">Side</button><button id="reset">Reset</button><button id="saveImage">Save image ↓</button><a class="button" href="estimate-preview.png" target="_blank">CAD render ↗</a></div><canvas id="canvas" tabindex="0"></canvas><div class="caption"><strong id="viewState">Estimated assembly</strong><span id="selectionCaption">Caliper · cable controls · offset adapter</span></div><div class="note">Image-based reconstruction.<br>Not a manufacturer model.</div></main></div><script id="assembly-data" type="application/json">'''+json.dumps(data,separators=(',',':'))+'''</script><script src="../viewer.bundle.js"></script></body></html>'''
(OUT/'index.html').write_text(html)
s=(ROOT/'render_preview.py').read_text().replace("'R05  /  INTEGRATED BRAKE HOUSING'","'CMD-23  /  IMAGE-BASED ESTIMATE'").replace("'238 × 200 × 58 mm  ·  two printed pieces'","'About 55 × 110 × 60 mm  ·  radial / tangential / axial'").replace("'Exact CAD mesh render. Estimate-based fit prototype; no powered-use rating.'","'Reference reconstruction. Body dimensions and mounting offsets are not verified.'").replace("render(0,'assembled-preview.png')","render(0,'estimate-preview.png')").replace("render(.8,'exploded-preview.png')","render(.8,'estimate-exploded.png')")
(OUT/'render_estimate.py').write_text(s)
print('Brake-only viewer written.')
